alter table public.midad_projects add column story text not null default '';
alter table public.midad_chapters add column writing_mode text not null default 'continuous' check(writing_mode in ('continuous','scenes'));
update public.midad_chapters c set writing_mode='scenes' where (select count(*) from public.midad_scenes s where s.chapter_id=c.id)>1;
create table public.midad_profiles(user_id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(username~'^[a-z0-9_]{3,30}$'),display_name text not null check(length(display_name) between 1 and 80),bio text not null default '' check(length(bio)<=1000),is_public boolean not null default false,created_at timestamptz not null default now());
alter table public.midad_profiles enable row level security;
create policy profile_select on public.midad_profiles for select to authenticated using(user_id=(select auth.uid()) or is_public);
create policy profile_insert on public.midad_profiles for insert to authenticated with check(user_id=(select auth.uid()));
create policy profile_update on public.midad_profiles for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy profile_delete on public.midad_profiles for delete to authenticated using(user_id=(select auth.uid()));
grant select,insert,update,delete on public.midad_profiles to authenticated;
create table public.midad_members(project_id uuid not null references public.midad_projects(id) on delete cascade,member_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('reader','editor')),created_at timestamptz not null default now(),primary key(project_id,member_id));
create index on public.midad_members(member_id);
alter table public.midad_members enable row level security;
create function midad_private.can_read(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.midad_projects where id=pid and user_id=(select auth.uid())) or exists(select 1 from public.midad_members where project_id=pid and member_id=(select auth.uid()))$$;
create function midad_private.can_write(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.midad_projects where id=pid and user_id=(select auth.uid())) or exists(select 1 from public.midad_members where project_id=pid and member_id=(select auth.uid()) and role='editor')$$;
create function midad_private.book_project(bid uuid) returns uuid language sql stable security definer set search_path='' as $$select project_id from public.midad_books where id=bid$$;
create function midad_private.chapter_project(cid uuid) returns uuid language sql stable security definer set search_path='' as $$select b.project_id from public.midad_chapters c join public.midad_books b on b.id=c.book_id where c.id=cid$$;
create function midad_private.scene_project(sid uuid) returns uuid language sql stable security definer set search_path='' as $$select b.project_id from public.midad_scenes s join public.midad_chapters c on c.id=s.chapter_id join public.midad_books b on b.id=c.book_id where s.id=sid$$;
create function midad_private.project_owner(pid uuid) returns uuid language sql stable security definer set search_path='' as $$select user_id from public.midad_projects where id=pid$$;
create function midad_private.original_chapter(cid uuid) returns boolean language sql stable security definer set search_path='' as $$select draft_id is null from public.midad_chapters where id=cid$$;
-- No privileged helper is a public RPC. RLS predicates are available to authenticated roles only.
grant usage on schema midad_private to authenticated;
revoke all on all functions in schema midad_private from public,anon;
grant execute on function midad_private.can_read(uuid),midad_private.can_write(uuid),midad_private.book_project(uuid),midad_private.chapter_project(uuid),midad_private.scene_project(uuid),midad_private.project_owner(uuid),midad_private.original_chapter(uuid) to authenticated;
create policy members_read on public.midad_members for select to authenticated using(member_id=(select auth.uid()) or midad_private.project_owner(project_id)=(select auth.uid()));
create policy members_insert on public.midad_members for insert to authenticated with check(midad_private.project_owner(project_id)=(select auth.uid()) and member_id<>(select auth.uid()));
create policy members_update on public.midad_members for update to authenticated using(midad_private.project_owner(project_id)=(select auth.uid())) with check(midad_private.project_owner(project_id)=(select auth.uid()));
create policy members_delete on public.midad_members for delete to authenticated using(midad_private.project_owner(project_id)=(select auth.uid()) or member_id=(select auth.uid()));
grant select,insert,update,delete on public.midad_members to authenticated;
drop policy owner_select on public.midad_projects;
create policy owner_select on public.midad_projects for select to authenticated using(midad_private.can_read(id));
drop policy owner_select on public.midad_books;
create policy owner_select on public.midad_books for select to authenticated using(midad_private.can_read(project_id));
-- Sharing grants manuscript access only; private planning, notes and world data stay owner-only.
do $$ declare tab text; pid text; readrule text; begin
 foreach tab in array array['chapters','scenes','revisions','annotations'] loop
 pid:=case when tab='chapters' then 'midad_private.book_project(book_id)' when tab='scenes' then 'midad_private.chapter_project(chapter_id)' else 'midad_private.scene_project(scene_id)' end;
 readrule:=case when tab='chapters' then format('midad_private.can_read(%s) and (draft_id is null or midad_private.can_write(%s))',pid,pid) when tab='scenes' then format('midad_private.can_read(%s) and (midad_private.original_chapter(chapter_id) or midad_private.can_write(%s))',pid,pid) else format('midad_private.can_write(%s)',pid) end;
 execute format('drop policy owner_select on public.midad_%I',tab);execute format('drop policy owner_insert on public.midad_%I',tab);execute format('drop policy owner_update on public.midad_%I',tab);execute format('drop policy owner_delete on public.midad_%I',tab);
 execute format('create policy owner_select on public.midad_%I for select to authenticated using (%s)',tab,readrule);
 execute format('create policy owner_insert on public.midad_%I for insert to authenticated with check(midad_private.can_write(%s) and user_id=midad_private.project_owner(%s))',tab,pid,pid);
 execute format('create policy owner_update on public.midad_%I for update to authenticated using(midad_private.can_write(%s)) with check(midad_private.can_write(%s) and user_id=midad_private.project_owner(%s))',tab,pid,pid,pid);
 execute format('create policy owner_delete on public.midad_%I for delete to authenticated using(midad_private.can_write(%s))',tab,pid);
 end loop;end $$;
create function midad_private.immutable_owner() returns trigger language plpgsql set search_path='' as $$begin if new.user_id<>old.user_id then raise exception 'owner_immutable';end if;return new;end$$;
do $$declare tab text;begin foreach tab in array array['projects','books','drafts','chapters','scenes','revisions','annotations','entities','notes','arcs','events','sessions','preferences','relationships'] loop execute format('create trigger protect_owner before update on public.midad_%I for each row execute function midad_private.immutable_owner()',tab);end loop;end$$;
create or replace function public.midad_save_scene(sid uuid,expected_version integer,document jsonb,prose text) returns setof public.midad_scenes language plpgsql security invoker set search_path='' as $$declare old public.midad_scenes;begin select * into old from public.midad_scenes where id=sid for update;if old.id is null then raise exception 'scene_not_found';end if;if old.version<>expected_version then raise exception 'version_conflict';end if;insert into public.midad_revisions(user_id,scene_id,content,plain_text,version) values(old.user_id,sid,old.content,old.plain_text,old.version);return query update public.midad_scenes set content=document,plain_text=prose,version=version+1,updated_at=now() where id=sid returning *;end$$;
create function public.midad_find_profile(handle text) returns table(user_id uuid,username text,display_name text,bio text) language sql stable security definer set search_path='' as $$select user_id,username,display_name,bio from public.midad_profiles where username=lower(handle) and auth.uid() is not null$$;
revoke all on function public.midad_find_profile(text) from public,anon;grant execute on function public.midad_find_profile(text) to authenticated;
create function public.midad_project_members(pid uuid) returns table(member_id uuid,role text,username text,display_name text) language sql stable security definer set search_path='' as $$select m.member_id,m.role,p.username,p.display_name from public.midad_members m left join public.midad_profiles p on p.user_id=m.member_id where m.project_id=pid and midad_private.project_owner(pid)=auth.uid()$$;
revoke all on function public.midad_project_members(uuid) from public,anon;grant execute on function public.midad_project_members(uuid) to authenticated;
create table public.midad_publications(chapter_id uuid primary key references public.midad_chapters(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,published_at timestamptz not null default now());
create index on public.midad_publications(user_id);alter table public.midad_publications enable row level security;
create policy publication_owner on public.midad_publications for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and midad_private.project_owner(midad_private.chapter_project(chapter_id))=(select auth.uid()) and midad_private.original_chapter(chapter_id));
grant select,insert,delete on public.midad_publications to authenticated;
create function public.midad_published_novels() returns table(id uuid,title text,description text,author_name text,author_username text,chapter_count bigint) language sql stable security definer set search_path='' as $$select p.id,p.title,p.description,coalesce(pr.display_name,'كاتب في مِداد'),pr.username,count(distinct pub.chapter_id) from public.midad_publications pub join public.midad_chapters c on c.id=pub.chapter_id join public.midad_books b on b.id=c.book_id join public.midad_projects p on p.id=b.project_id left join public.midad_profiles pr on pr.user_id=p.user_id where c.draft_id is null group by p.id,pr.display_name,pr.username$$;
create function public.midad_public_chapters(pid uuid) returns table(id uuid,title text,"position" integer,content jsonb,plain_text text) language sql stable security definer set search_path='' as $$select c.id,c.title,c.position,jsonb_build_object('type','doc','content',coalesce((select jsonb_agg(block order by s.position,s.id,block_no) from public.midad_scenes s cross join lateral jsonb_array_elements(s.content->'content') with ordinality as blocks(block,block_no) where s.chapter_id=c.id),'[]'::jsonb)),coalesce((select string_agg(s.plain_text,E'\n\n' order by s.position,s.id) from public.midad_scenes s where s.chapter_id=c.id),'') from public.midad_publications pub join public.midad_chapters c on c.id=pub.chapter_id join public.midad_books b on b.id=c.book_id where b.project_id=pid and c.draft_id is null order by c.position,c.id$$;
revoke all on function public.midad_published_novels(),public.midad_public_chapters(uuid) from public;
grant execute on function public.midad_published_novels(),public.midad_public_chapters(uuid) to anon,authenticated;
